query:
UPDATE course_lessons SET content = REPLACE(content, 
  'S = 1600 x (0.225) + 48 = 408mm minimum distance from hazard',
  'Initial calculation: S = 1600 × 0.225 + 48 = 408mm. **However**, since 408mm < 500mm, ISO 13855 requires recalculation using K = 2000 mm/s: S = 2000 × 0.225 + 48 = **498mm minimum distance from hazard**. Always verify: if result < 500mm, recalculate with K = 2000'
) WHERE id = 90014;

